from pathlib import Path
import json
R=Path(__file__).resolve().parent;S=R/'source/official';commit=json.loads((R/'source/provenance.json').read_text())['commit']
sources=[dict(id=i,kind='code',locator=f'https://github.com/andyz245/LanguageAgentTreeSearch/blob/{commit}/{p}',text=(S/p).read_text()) for i,p in [('lats','hotpot/lats.py'),('task','hotpot/hotpotqa.py'),('env','hotpot/wikienv.py'),('reward','hotpot/wrappers.py'),('entry','hotpot/run.py')]]
def evidence(i,q):
 assert q in next(s['text'] for s in sources if s['id']==i),(i,q)
 return [dict(source=i,quote=q)]
def node(i,label,role,src,q,detail=''):return dict(id=i,label=label,detail=detail,role=role,status='neutral',phase='inference',evidence=evidence(src,q))
nodes=[node('question','Question','input','lats','x = env.reset(idx=idx)'),node('tree','Trajectory tree','memory','lats','root = Node(state=None, question=x)','This question'),node('select','Select (UCT)','neutral','lats','node = select_node(root)'),node('policy','Expand','core','lats','samples = gpt(prompt, n=n_generate_sample, stop=stop)','LM candidates'),node('tools','Shared WikiEnv','tool','lats',"obs, r, done, info = step(env, f\"{action_type.lower()}[{action_param}]\")",'Search / Lookup / Finish'),node('value','LM value','core','task','prompt = value_prompt_reasoning.format(s="", input=inp)','Base value prompt'),node('rollout','Value-guided rollout','neutral','lats','while not node.is_terminal and depth < max_depth:','Absolute depth < 4'),node('backup','Backup','neutral','lats','backpropagate(terminal_node, reward)','If no success'),node('failed','Failed traces','memory','lats',"failed_trajectories.append({'trajectory': trajectory, 'final_answer': f\"{action_type.lower()}[{action_param}]\"})",'Wrong terminal'),node('reflect','Self-reflection','core','lats','if len(unique_trajectories) > len(reflection_map) and len(unique_trajectories) < 4:','New distinct failures: 1-3 total'),node('context','Reflection context','memory','lats','reflection_map = task.generate_self_reflection(unique_trajectories, x)','This question'),node('result','Return state','output','lats','return best_child.state, best_child.value, all_nodes, best_child.reward, best_child.em','Success / budget fallback')]
def edge(i,a,b,k,src,q,label=''):return dict(id=i,**{'from':a,'to':b},kind=k,label=label,status='neutral',phase='inference',evidence=evidence(src,q))
edges=[edge('initialize','question','tree','data','lats','root = Node(state=None, question=x)'),edge('select-path','tree','select','control','lats','node = select_node(root)'),edge('expand-path','select','policy','control','lats','expand_node(node, args, task)'),edge('execute','policy','tools','control','lats',"obs, r, done, info = step(env, f\"{action_type.lower()}[{action_param}]\")"),edge('store-children','tools','tree','feedback','lats','node.children.extend(new_nodes)','Expansion children'),edge('candidate-values','tree','value','data','lats',"child_prompts = [generate_prompt(child) for child in node.children if not child.is_terminal]"),edge('best-child','value','rollout','control','lats','rollout(max(node.children, key=lambda child: child.value), args, task, idx, max_depth=4)'),edge('rollout-step','rollout','tools','feedback','lats','new_states = generate_new_states(node, args, task, n)','Reuse policy + tools'),edge('rollout-feedback','tools','rollout','feedback','lats','return state.reward, state','Observation / terminal reward'),edge('no-success','rollout','backup','control','lats','backpropagate(terminal_node, reward)'),edge('update-statistics','backup','tree','feedback','lats','node.visits += 1','Values + visits'),edge('terminal-failure','tools','failed','feedback','lats','if new_node.is_terminal and r == 0:'),edge('reflect-failures','failed','reflect','data','lats','if len(unique_trajectories) > len(reflection_map) and len(unique_trajectories) < 4:'),edge('store-reflection','reflect','context','data','task',"'reflection': reflection[0]"),edge('policy-feedback','context','policy','feedback','task','prompt = cot_prompt_feedback.format(trajectories=trajectories, input=input)'),edge('return-tree','tree','result','control','lats','best_child = max(all_nodes_list, key=lambda x: x.reward)','Terminal / fallback'),edge('return-rollout','rollout','result','control','lats','return terminal_node.state, terminal_node.value, [], terminal_node.reward, terminal_node.em','Successful terminal')]
spec=dict(version='1.0',title='Code-grounded LATS HotPotQA',subtitle='',sources=sources,claims=dict(summary='Question-scoped trajectory search with LM values and failure-guided generation',innovation=None,baseline=None,scope='Official HotPotQA --algorithm lats --prompt_sample cot; shared mutable environment; reflection-to-policy only; not a claim of full-paper implementation equivalence.'),nodes=nodes,edges=edges,groups=[],assumptions=['Scope and known implementation hazards are retained in METHOD.md and the independent source audit.','Tree motif is illustrative, not an observed execution or a literal branching-factor/layer count.','Rollout endpoints keep parent links but are not appended to ordinary children.','Return state may be unsuccessful on budget fallback; no deployment-time success guarantee.','No reflection-to-value edge: returned base prompt overwrites attempted feedback prompt.'],layout=dict(canvas=dict(width=1800,height=1000),direction='LR',nodes={},edges={}),visual=dict(theme='paper',publicationWidthIn=7,minTextPt=7,showTitle=False,showSubtitle=False,showLegend=False,typography=dict(fontFamily='Arial',moduleSize=32,detailSize=27,annotationSize=27)))
(R/'spec.json').write_text(json.dumps(spec,indent=2)+'\n')
(R/'design-contract.json').write_text(json.dumps({'scope':spec['claims']['scope'],'publicationWidthIn':7,'noTitleOrFooter':True,'solidFillsOnly':True,'palette':{'#E8F1FB':{'meaning':'Language-model inference','nodes':['policy','value','reflect']},'#E8F4EC':{'meaning':'Question-scoped stored state','nodes':['tree','failed','context']},'#F6F7F8':{'meaning':'Neutral I/O, environment, or control','nodes':['question','select','tools','rollout','backup','result']},'#BF8A20':{'meaning':'Selected trajectory only','channel':'tree motif path + selection wire'}},'visualFocus':'Branching trajectory tree, not equally weighted generic cards','designStudy':'Generated visual proposal, with source-required deviations: no reflection critic feedback, no UCT inside rollout, no rollout-child retention, no gradients. Not claimed as pixel-faithful reconstruction.','authorFigureHiddenUntilNativeFreeze':True,'readableMinimumPixelsAt7in':25,'sourceFactsOverrideGeneratedImage':True},indent=2)+'\n')
print('Wrote semantic spec:',len(nodes),'nodes',len(edges),'edges')
